if (!context.panel.data?.series?.length) return {};



const series = context.panel.data.series[0];
const timeField = series.fields.find(f => f.name === 'time');
const rackField = series.fields.find(f => f.name === 'rackId');
const powerField = series.fields.find(f => f.name === 'mean_power_w');

if (!timeField || !rackField || !powerField) return {};

// Group by rackId → { rackId: [[time, value], ...] }
const racks = {};
for (let i = 0; i < rackField.values.length; i++) {
  const rack = rackField.values[i] ?? '(unknown)';
  const t = timeField.values[i];
  const power = powerField.values[i];
  if (!racks[rack]) racks[rack] = [];
  racks[rack].push([t, power]);
}

const COLORS = [
  '#FFA314', '#00C8FF', '#00E5A0', '#FF6B6B',
  '#B57BFF', '#FFD166', '#06D6A0', '#EF476F',
  '#118AB2', '#FF9F1C', '#A8DADC', '#E76F51'
];

const rackIds = Object.keys(racks).sort();

const chartSeries = rackIds.map((rack, idx) => ({
  name: rack,
  type: 'line',
  smooth: true,
  symbol: 'circle',
  symbolSize: 5,
  showSymbol: false,
  sampling: 'lttb',
  lineStyle: { width: 2, color: COLORS[idx % COLORS.length] },
  itemStyle: { color: COLORS[idx % COLORS.length] },
  areaStyle: {
    color: {
      type: 'linear', x: 0, y: 0, x2: 0, y2: 1,
      colorStops: [
        { offset: 0, color: COLORS[idx % COLORS.length].replace(')', ', 0.25)').replace('rgb', 'rgba') + '' },
        { offset: 1, color: 'rgba(0,0,0,0)' }
      ]
    }
  },
  emphasis: { focus: 'series', lineStyle: { width: 3 } },
  data: racks[rack].sort((a, b) => a[0] - b[0])
}));

return {
  backgroundColor: 'transparent',
  animation: true,
  grid: { top: 40, right: 20, bottom: 60, left: 70, containLabel: false },
  tooltip: {
    trigger: 'axis',
    backgroundColor: '#051C2D',
    borderColor: '#FFA314',
    borderWidth: 1,
    textStyle: { color: '#F5F5F5', fontSize: 12 },
    axisPointer: {
      type: 'cross',
      lineStyle: { color: '#FFA314', opacity: 0.5 },
      crossStyle: { color: '#FFA314', opacity: 0.3 }
    },
    formatter: params => {
      const time = new Date(params[0].value[0]).toLocaleString();
      const rows = params
        .sort((a, b) => b.value[1] - a.value[1])
        .map(p => `<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${p.color};margin-right:5px"></span>${p.seriesName}: <b>${p.value[1]?.toFixed(1)} W</b>`)
        .join('<br/>');
      return `<div style="font-size:11px;color:#aaa;margin-bottom:4px">${time}</div>${rows}`;
    }
  },
  legend: {
    type: 'scroll',
    bottom: 0,
    itemWidth: 14,
    itemHeight: 4,
    itemGap: 14,
    borderRadius: 2,
    textStyle: { color: '#F5F5F5', fontSize: 11 },
    pageTextStyle: { color: '#F5F5F5' },
    pageIconColor: '#FFA314',
    pageIconInactiveColor: '#bfbfbf'
  },
  xAxis: {
    type: 'time',
    axisLine: { lineStyle: { color: '#2a4a6a' } },
    axisLabel: { color: '#8899aa', fontSize: 11 },
    splitLine: { lineStyle: { color: '#0d2035', type: 'dashed' } },
    axisTick: { lineStyle: { color: '#2a4a6a' } }
  },
  yAxis: {
    type: 'value',
    name: 'Power (W)',
    nameTextStyle: { color: '#8899aa', fontSize: 11 },
    axisLine: { lineStyle: { color: '#2a4a6a' } },
    axisLabel: { color: '#8899aa', fontSize: 11, formatter: v => `${v} W` },
    splitLine: { lineStyle: { color: '#0d2035', type: 'dashed' } }
  },
  series: chartSeries
};
